while True:
    if turns >= limits.max_turns:
        return done(StopReason.MAX_TURNS)
    if cost >= limits.max_cost_usd:
        return done(StopReason.BUDGET)
    remaining = limits.max_seconds - (clock() - start)
    if remaining <= 0:
        return done(StopReason.TIMEOUT)
    try:  # 호출 타임아웃도 남은 시간으로 제한
        resp = client.messages.create(
            ..., messages=messages, timeout=remaining)
    except anthropic.APITimeoutError:
        return done(StopReason.TIMEOUT)

results = []
for block in resp.content:
    if block.type != "tool_use": continue
    fn = registry.get(block.name)
    if fn is None:
        out, is_err = f"알 수 없는 도구: {block.name}", True
    else:
        try: out, is_err = fn(**block.input), False
        except Exception as e:
            out, is_err = f"{type(e).__name__}: {e}", True
    results.append({
        "type": "tool_result", "tool_use_id": block.id,
        "content": str(out), "is_error": is_err})
messages.append({"role": "user", "content": results})

def handle_result(r: ResultMessage):
    s = {"reason": r.subtype, "turns": r.num_turns,
         "cost_usd": r.total_cost_usd,
         "session_id": r.session_id}
    if r.subtype == "success":
        s["text"] = r.result
    elif r.subtype in ("error_max_turns",
                       "error_max_budget_usd"):
        s["resumable"] = True   # session_id로 resume(8장)
    else:
        s["resumable"] = False  # 구조화 출력 재시도 초과 등
    return s
